"""Standalone job scraper for f22labs.com (India roles). Generated by the agent; runs with NO LLM calls.
Run:  python scraper.py [output.jsonl]
source_type=embedded_json, pagination=page_number.
"""

import json
import os
import sys
import time
from datetime import datetime
from html import unescape
from urllib.parse import urljoin, urlparse, parse_qs

import requests
from bs4 import BeautifulSoup


def parse_html(text):
    if isinstance(text, bytes):
        text = text.decode("utf-8", errors="replace")
    text = text or ""
    soup = BeautifulSoup(text, "lxml")
    for tag in ("input", "script", "a"):
        raw_count = text.count("<" + tag)
        if raw_count >= 2 and len(soup.find_all(tag)) < raw_count // 2:
            return BeautifulSoup(text, "html.parser")
    return soup


_INDIA_CITY_FALLBACK = {
    "bengaluru": "Bengaluru", "bangalore": "Bangalore", "mumbai": "Mumbai", "delhi": "Delhi",
    "new delhi": "New Delhi", "gurugram": "Gurugram", "gurgaon": "Gurgaon", "noida": "Noida",
    "hyderabad": "Hyderabad", "chennai": "Chennai", "pune": "Pune", "kolkata": "Kolkata",
    "ahmedabad": "Ahmedabad",
}

def resolve_location(location_raw):
    # returns (city, state, country, country_code) -- all None if unresolvable, never guessed.
    if not location_raw:
        return (None, None, None, None)
    first_segment = location_raw.split(";")[0].strip()  # some platforms join multiple locations with ';'
    parts = [p.strip() for p in first_segment.split(",")]
    if len(parts) >= 2:
        # explicit "City, [State,] Country" format -- last segment is the country
        city = parts[0] or None
        state = parts[1] if len(parts) >= 3 else None
        country_raw = parts[-1]
        if country_raw.lower() in ("india", "in"):
            return (city, state, "India", "IN")
        return (city, state, country_raw or None, None)
    # no comma: bare city name -- only resolve via the small generic fallback dict, never guess otherwise
    bare = first_segment.lower()
    if bare in _INDIA_CITY_FALLBACK:
        return (_INDIA_CITY_FALLBACK[bare], None, "India", "IN")
    return (None, None, None, None)


HEADERS = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "en-US,en;q=0.9",
}

BASE_LIST_URL = "https://f22labs.zohorecruit.in/jobs/Careers"


def eprint(msg):
    print(msg, file=sys.stderr)


def request_with_retries(session, url, params=None):
    delays = [1, 2, 4]
    last_status = None
    for attempt in range(4):
        try:
            resp = session.get(url, params=params, headers=HEADERS, timeout=30)
            last_status = resp.status_code
            if resp.status_code < 400:
                return resp
            if resp.status_code in (403, 429) or 500 <= resp.status_code < 600:
                if attempt < 3:
                    time.sleep(delays[attempt])
                    continue
                return resp
            return resp
        except requests.RequestException:
            if attempt < 3:
                time.sleep(delays[attempt])
                continue
            break
    raise RuntimeError(f"request failed for {url} (last_status={last_status})")


def parse_iso_date(text):
    if not text:
        return None
    candidates = [text.strip()]
    for s in candidates:
        try:
            return datetime.fromisoformat(s.replace("Z", "+00:00")).date().isoformat()
        except Exception:
            pass
        for fmt in ("%Y-%m-%d", "%d-%m-%Y", "%m/%d/%Y", "%d/%m/%Y", "%b %d, %Y", "%B %d, %Y"):
            try:
                return datetime.strptime(s, fmt).date().isoformat()
            except Exception:
                pass
    return None


def extract_jobs_from_hidden_input(soup):
    jobs = []
    for inp in soup.find_all("input"):
        attrs = {k.lower(): v for k, v in inp.attrs.items()}
        if attrs.get("type") == "hidden" and attrs.get("id") == "jobs":
            raw = inp.get("value")
            if raw:
                try:
                    data = json.loads(raw)
                    if isinstance(data, list):
                        jobs = data
                    elif isinstance(data, dict):
                        for key in ("jobs", "data", "results", "records"):
                            if isinstance(data.get(key), list):
                                jobs = data[key]
                                break
                    return jobs
                except Exception:
                    return []
    return []


def extract_meta(soup):
    for inp in soup.find_all("input"):
        attrs = {k.lower(): v for k, v in inp.attrs.items()}
        if attrs.get("type") == "hidden" and attrs.get("id") == "meta":
            raw = inp.get("value")
            if raw:
                try:
                    return json.loads(raw)
                except Exception:
                    return {}
    return {}


def extract_detail_fields(html_text):
    soup = parse_html(html_text)
    title = None
    if soup.title and soup.title.get_text(strip=True):
        title = soup.title.get_text(" ", strip=True)
    desc = None
    for sel in ["div.job-description", "div.description", "section.job-description", "article", "main"]:
        node = soup.select_one(sel)
        if node:
            txt = node.get_text(" ", strip=True)
            if txt:
                desc = unescape(txt)
                break
    return title, desc


def build_record_from_job(job, detail_url=None, detail_title=None, detail_desc=None):
    title = job.get("Posting_Title") if isinstance(job, dict) else None
    if not title:
        title = detail_title
    location_raw = job.get("City") if isinstance(job, dict) else None
    city, state, country, country_code = resolve_location(location_raw)
    work_type = None
    if isinstance(job, dict) and "Remote_Job" in job:
        work_type = "Remote" if job.get("Remote_Job") is True else "Onsite" if job.get("Remote_Job") is False else None
    job_id = None
    if isinstance(job, dict):
        for k in ("JobId", "job_id", "id", "Job_ID", "JobID"):
            if job.get(k) is not None:
                job_id = str(job.get(k))
                break
    if not job_id and detail_url:
        path = urlparse(detail_url).path.rstrip("/").split("/")
        if len(path) >= 4 and path[-3] == "Careers":
            job_id = path[-2]
    date_posted_text = None
    date_posted = None
    for k in ("Date_Posted", "Posted_Date", "date_posted", "Posting_Date"):
        if isinstance(job, dict) and job.get(k):
            date_posted_text = str(job.get(k))
            date_posted = parse_iso_date(date_posted_text)
            break
    return {
        "title": title if title else None,
        "job_id": str(job_id) if job_id else None,
        "location": {"city": city, "state": state, "country": country, "country_code": country_code},
        "url": detail_url if detail_url else None,
        "apply_url": detail_url if detail_url else None,
        "date_posted": date_posted,
        "date_posted_text": date_posted_text,
        "job_description": detail_desc if detail_desc else (unescape(job.get("Job_Description")) if isinstance(job, dict) and job.get("Job_Description") else None),
        "employment_type": None,
        "work_type": work_type,
        "salary_range": None,
    }


def main():
    out_path = sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(os.path.abspath(__file__)), "output.jsonl")
    session = requests.Session()
    seen = set()
    wrote_any = False
    try:
        with open(out_path, "w", encoding="utf-8") as outf:
            page = 1
            while True:
                resp = request_with_retries(session, BASE_LIST_URL, params={"page": str(page)})
                if resp.status_code == 403:
                    eprint(f"blocked on list page {page}: 403")
                    break
                if resp.status_code >= 400:
                    raise RuntimeError(f"list page {page} failed with HTTP {resp.status_code}")
                soup = parse_html(resp.text)
                jobs = extract_jobs_from_hidden_input(soup)
                meta = extract_meta(soup)
                links = []
                for a in soup.select('a[href*="/jobs/Careers/"]'):
                    href = a.get("href")
                    if href:
                        links.append(urljoin(BASE_LIST_URL, href))
                page_records = []
                for job in jobs if isinstance(jobs, list) else []:
                    detail_url = None
                    if isinstance(job, dict):
                        for k in ("Job_Url", "job_url", "url", "JobURL"):
                            if job.get(k):
                                detail_url = urljoin(BASE_LIST_URL, str(job.get(k)))
                                break
                    if not detail_url and links:
                        for link in links:
                            if "/jobs/Careers/" in link:
                                detail_url = link
                                break
                    rec = build_record_from_job(job, detail_url=detail_url)
                    dedupe_key = rec["job_id"] or rec["url"]
                    if not dedupe_key:
                        continue
                    if dedupe_key in seen:
                        continue
                    seen.add(dedupe_key)
                    page_records.append((dedupe_key, rec))
                if not jobs and not links:
                    break
                if len(page_records) == 0:
                    break
                for _, rec in page_records:
                    if rec["location"]["country_code"] == "IN" or rec["location"]["country"] == "India":
                        outf.write(json.dumps(rec, ensure_ascii=False) + "\n")
                        wrote_any = True
                page += 1
                time.sleep(0.35)
                if page > 100:
                    break
        if not wrote_any:
            open(out_path, "w", encoding="utf-8").close()
        return 0
    except Exception as exc:
        try:
            open(out_path, "a", encoding="utf-8").close()
        except Exception:
            pass
        eprint(f"error: {exc}")
        return 1


if __name__ == "__main__":
    sys.exit(main())